// useGlanceFaults (#2265) — the unresolved runtime-fault summary per project, for the Glance node
// FAULT-health badge. Polls the backend on a slow cadence and returns a `{ projectKey → summary }`
// map the workspace merges into the graph nodes.
// Orthogonal to the liveness "live/down" status (#2263): this reads the fault stores, that reads
// heartbeats, so the two merge into the node without touching each other.
//
// Degrades to an empty map when a project has no errordb yet — a project with zero faults simply
// shows no badge.
import { useEffect, useRef, useState } from "react";
import { usePoll } from "@/shared/hooks/usePoll";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import type { FaultLevel } from "@/shared/lib/fleet/faultTriage";

const POLL_MS = 20_000;

/** The per-project fault summary the health axis reads (#2541): the total unresolved `count`, plus the
 *  worst open fault's `level` (drives the dot colour) and `title` (the bottom-right reason text).
 *
 *  THE BACKEND DERIVES THIS NOW — it is `FaultSummary` in `observability::collector`, ranked by
 *  `bsc_fleet::fault_triage::worst_fault`. The declaration here is the wire shape, not a second
 *  computation of it. */
export interface GlanceFault { count: number; level: FaultLevel; title: string }

/** Unresolved-fault summaries keyed by project plan key. `keys` is the current Glance project set; the
 *  map only carries projects with at least one unresolved fault (absent ⇒ healthy/idle). */
export function useGlanceFaults(keys: string[]): Record<string, GlanceFault> {
  const [counts, setCounts] = useState<Record<string, GlanceFault>>({});
  // Stable join so the poll re-subscribes only when the actual key SET changes, not every render (the
  // parent passes a fresh array each time).
  const keyList = keys.slice().sort();
  const joined = keyList.join(" ");
  const keysRef = useRef(keyList);
  useEffect(() => { keysRef.current = keyList; }, [keyList]);

  usePoll(async (isCancelled) => {
    if (isCancelled()) return;
    const targets = keysRef.current;
    if (targets.length === 0) { setCounts({}); return; }
    // ONE call for the whole set, and the whole ANSWER comes back — not the rows to rank here.
    //
    // #3912 already replaced a `bsc errors list` subprocess PER PROJECT (at 28 projects on a 20s
    // cadence, ~21 concurrent spawns three times a minute — the single largest consumer of the
    // command queue) with one in-process read. What stayed behind was the ranking: this hook took
    // every unresolved row over the IPC boundary and ran `worstFault`/`unresolvedCount` inside a
    // `targets.map(…)`, i.e. once per project, in the renderer. Both halves now happen once, in the
    // process that owns error.db, using the port that was already proved equal to that TypeScript by
    // a fixture generated from it (`bsc_fleet::fault_triage`).
    //
    // A project absent from the map has no error.db, no faults, or none still open — the same "no
    // badge" outcome the per-project read produced by degrading to [].
    const byKey = await safeInvoke<Record<string, GlanceFault>>("fault_summaries_batch", { projectKeys: targets }, {});
    if (isCancelled()) return;
    setCounts(byKey ?? {});
  }, POLL_MS, [joined]); // re-subscribe when the key SET changes (via the stable join)

  return counts;
}
